#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Linq;
using MVZ2Logic.Resources;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.Sprites
{
    /// <summary>
    /// 全局Sprite解析器。
    /// </summary>
    public class SpriteResolver
    {
        public void AddProvider(ISpriteProvider db)
        {
            var index = providers.BinarySearch(db, comparer);
            if (index < 0)
            {
                providers.Insert(~index, db);
            }
        }
        public bool RemoveProvider(ISpriteProvider db)
        {
            return providers.Remove(db);
        }
        public void ClearProviders()
        {
            providers.Clear();
        }

        /// <summary>
        /// 解析Sprite。
        /// </summary>
        public Sprite? Resolve(SpriteReference reference, SpriteVariantContext context)
        {
            List<SpriteLookupKey> candidateKeys = BuildCandidateReferences(reference, context);

            foreach (ISpriteProvider db in providers)
            {
                foreach (SpriteLookupKey candidate in candidateKeys)
                {
                    if (db.TryGet(candidate, out var sprite))
                    {
                        return sprite;
                    }
                }
            }

            Log.LogWarning($"Sprite not found: {reference}");
            return null;
        }

        private List<SpriteLookupKey> BuildCandidateReferences(SpriteReference reference, SpriteVariantContext context)
        {
            var list = new List<SpriteLookupKey>();
            if (!string.IsNullOrEmpty(context.languageCode) && context.censored)
            {
                list.Add(new SpriteLookupKey(reference, SpriteHelper.SPRITE_TAG_CENSORED, SpriteHelper.GetLanguageSpriteTag(context.languageCode)));
            }
            if (!string.IsNullOrEmpty(context.languageCode))
            {
                list.Add(new SpriteLookupKey(reference, SpriteHelper.GetLanguageSpriteTag(context.languageCode)));
            }
            if (context.censored)
            {
                list.Add(new SpriteLookupKey(reference, SpriteHelper.SPRITE_TAG_CENSORED));
            }

            list.Add(new SpriteLookupKey(reference));

            return list;
        }
        private readonly List<ISpriteProvider> providers = new();
        private readonly Comparer comparer = new();

        private class Comparer : IComparer<ISpriteProvider>
        {
            public int Compare(ISpriteProvider x, ISpriteProvider y)
            {
                return y.Priority.CompareTo(x.Priority);
            }
        }
    }
    public class SpriteLookupKey : IEquatable<SpriteLookupKey>
    {
        public SpriteReference reference;
        public HashSet<string> tags = new HashSet<string>();

        public SpriteLookupKey(SpriteReference reference, params string[] tags)
        {
            this.reference = reference;
            foreach (var tag in tags)
            {
                this.tags.Add(tag);
            }
        }
        public override bool Equals(object obj)
        {
            if (obj is SpriteLookupKey other)
            {
                return Equals(other);
            }
            return base.Equals(obj);
        }
        public override int GetHashCode()
        {
            var hash = reference.GetHashCode(); 
            foreach (var item in tags)
            {
                if (item != null)
                {
                    // 使用异或运算，确保顺序无关性
                    // 注意：如果集合中有重复元素（针对List），异或可能会导致抵消，
                    // 但对于 HashSet 来说是安全的。
                    hash ^= item.GetHashCode();
                }
            }
            return hash;
        }
        public override string ToString()
        {
            return $"{reference}({string.Join(',', tags)})";
        }
        public bool Equals(SpriteLookupKey other)
        {
            return reference == other.reference && tags.SetEquals(other.tags);
        }
    }
}
